WITH session_stats AS (SELECT session_id, AVG(duration_sec) AS avg_duration_sec, SUM(CASE WHEN event_type = 'click' THEN duration_sec ELSE 0 END) AS click_duration_sec FROM web_events WHERE page IN ('/search', '/checkout') GROUP BY session_id) SELECT sessions.browser, session_stats.avg_duration_sec, session_stats.click_duration_sec FROM sessions INNER JOIN session_stats ON sessions.id = session_stats.session_id WHERE session_stats.avg_duration_sec > 420 ORDER BY avg_duration_sec DESC;
